122	  auto andes_supported_csr = [&](std::string_view name) {
123	    if (andes_supported.empty()) return true;
124	    for (const std::string& s : andes_supported)
125	      if (s == name) return true;
126	    return false;
127	  };
128	  // v6 write-mask gate: skip any mask-governed CSR the program never WROTE
129	  // (per the oracle's mask, which covers boot + ROI). Unwritten CSRs hold
130	  // QEMU's reset default in `ref` but the engine's own RTL reset in `got`
131	  // (the restore skipped them too), so comparing would false-positive on
132	  // every reset-value divergence. Flag clear = pre-v6 file = compare all.
133	  auto wm_live = [&](int slot) {
134	    if (!(ref.flags & HYBRID_FLAG_WRITE_MASK)) return true;
135	    return hybrid_wm_test(ref.write_mask, static_cast<unsigned>(slot)) != 0;
136	  };
137	  if (ref.flags & HYBRID_FLAG_ANDES) {
138	#define X(field, addr, name)                                     \
139	  if (!andes_verify_excluded(name) && andes_supported_csr(name)  \
140	      && wm_live(HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field)) \
141	    cmp(r, name, ref.andes.field, got.andes.field);
142	    HYBRID_ANDES_CSR_LIST(X)
143	#undef X
144	    if (andes_supported_csr("pmacfg"))
145	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
146	        if (wm_live(HYBRID_WM_PMACFG_BASE + i))
147	          cmp(r, "pmacfg" + std::to_string(i), ref.andes.pmacfg[i],
148	              got.andes.pmacfg[i]);
149	    if (andes_supported_csr("pmaaddr"))
150	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
151	        if (wm_live(HYBRID_WM_PMAADDR_BASE + i))
152	          cmp(r, "pmaaddr" + std::to_string(i), ref.andes.pmaaddr[i],
153	              got.andes.pmaaddr[i]);
154	  }
155	
156	  // M-ext CSR block (v4): same gate (the engine's supported list now includes
157	  // the M-ext names) and the same HW-driven exclusion. A CSR the engine lacks
158	  // is neither restored, drained, nor compared.
159	  if (ref.flags & HYBRID_FLAG_M_EXT) {
160	#define X(field, addr, name)                                     \
161	  if (!andes_verify_excluded(name) && andes_supported_csr(name)  \
162	      && wm_live(HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field)) \
163	    cmp(r, name, ref.m_ext.field, got.m_ext.field);
164	    HYBRID_M_EXT_CSR_LIST(X)
165	#undef X
166	  }
167	
168	  // L2C MMIO config (v5): the L2C Control Register round-trips (restored at
169	  // resume, re-read at drain), so compare its RW config bits (CEN, prefetch,
170	  // ECC, RAM timing). INITSTATUS[14] is a read-only status bit -- a real L2C
171	  // model drives it, QEMU's RAM stub does not -- so mask it to avoid a false
172	  // positive. Only the writable Control Register is verified; the read-only
173	  // Configuration Register and the volatile CCTL/error/counter registers are
174	  // captured but not restored, so they are not compared.
175	  if (ref.flags & HYBRID_FLAG_L2C) {
176	    const uint64_t rw_mask = ~(uint64_t{1} << 14);  // clear INITSTATUS[14]
177	    cmp(r, "l2c.ctrl",
178	        ref.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & rw_mask,
179	        got.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] & rw_mask);
180	  }
181	
182	  return r;
183	}
