185	std::vector<std::string> unsupported_written_csrs(
186	    const hybrid_state_v1& st, const std::vector<std::string>& andes_supported) {
187	  std::vector<std::string> out;
188	  if (!(st.flags & HYBRID_FLAG_WRITE_MASK)) return out;  // pre-v6: no info
189	  if (andes_supported.empty()) return out;               // no engine info
190	
191	  const auto supported = [&](std::string_view name) {
192	    for (const std::string& s : andes_supported)
193	      if (s == name) return true;
194	    return false;
195	  };
196	  const auto written = [&](int slot) {
197	    return hybrid_wm_test(st.write_mask, static_cast<unsigned>(slot)) != 0;
198	  };
199	
200	  // Andes scalars. ucode is skipped: the plugin sets its bit unconditionally
201	  // (transport-always DSP flag), so it carries no real write information.
202	#define X(field, addr, name)                                              \
203	  if (std::string_view{name} != "ucode"                                   \
204	      && written(HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field)      \
205	      && !supported(name))                                                \
206	    out.push_back(name);
207	  HYBRID_ANDES_CSR_LIST(X)
208	#undef X
209	
210	  // PMA: one group marker each, matching the --describe list's convention.
211	  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
212	    if (written(HYBRID_WM_PMACFG_BASE + i) && !supported("pmacfg")) {
213	      out.push_back("pmacfg");
214	      break;
215	    }
216	  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
217	    if (written(HYBRID_WM_PMAADDR_BASE + i) && !supported("pmaaddr")) {
218	      out.push_back("pmaaddr");
219	      break;
220	    }
221	
222	#define X(field, addr, name)                                              \
223	  if (written(HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field)         \
224	      && !supported(name))                                                \
225	    out.push_back(name);
226	  HYBRID_M_EXT_CSR_LIST(X)
227	#undef X
228	
229	  return out;
230	}
